    // ***** WIP *****

    /// <summary>
    /// Perform substitution checks/updates at point of order line entry. Relates to
    /// the "Always" substitution code.
    /// </summary>
    /// <param name = "_salesLine">_salesLine</param>
    /// <param name = "_interactive">_interactive</param>
    /// <returns>Validation result</returns>
    public static boolean checkSalesLineAtCreation(
        SalesLine               _salesLine,
        boolean                 _interactive = true)
    {
        boolean                                 ret = true;

        METSalesItemSubstitute                  itemSub;
        METSalesItemSubstitutionParentChild     parentChild;
        ItemId                                  replacementItemID; 
        InventDim                               inventDim   = _salesLine.inventDim();
        SalesTable                              salesTable  = _salesLine.salesTable();
        METSalesItemSubstitutionAccountRelation subsGroup   = salesTable.custTable_CustAccount().CustGroup;
  
        boolean yesNoPrompt(str _msg)
        {
            // TODO - use this instead of Box::YesNo - if _interactive is 
            // false, assume confirmation, eg from service (tbd).
            return true;
        }

        if(!_salesLine.metSubstitutionsActive())
        {
            // Subs not applicable to this line. 
            return true;
        }

        select firstonly parentChild
            where   parentChild.InventSiteId    == inventDim.InventSiteId
            &&      parentChild.ChildItemID     == _salesLine.ItemId;

        if(parentChild)
        {
            if(_interactive)
            {
                if(Box::yesNo(strFmt("Child item number %1 will be replaced by the Parent item number %2",
                    parentChild.ChildItemID,
                    parentChild.ParentItemID), DialogButton::No) == DialogButton::Yes)
                {
                    replacementItemID = parentChild.ParentItemID;
                }
                else
                {
                    // Prompted for replacement based on parent/child but user cancelled updated.
                    ret = checkFailed(strfmt("Item %1 cannot be selected as it has a parent/child substitution defined.", _salesLine.ItemId));
                }
            }   
            else
            {
                replacementItemID = parentChild.ParentItemID;
            }
        }
        else
        {
            select firstonly itemSub
                order by AccountCode asc
                where   itemSub.ItemId              == _salesLine.ItemId
                &&      itemSub.InventSiteId        == inventDim.InventSiteId
                &&      itemSub.SubstitutionCode    == METSalesItemSubstitutionCode::Always
                &&  (   // table/group/all match 
                    (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::Table && 
                     itemSub.AccountRelation == salesTable.CustAccount)
                ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::GroupId && 
                     itemSub.AccountRelation == subsGroup)
                ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::All &&
                     itemSub.AccountRelation == '')
                );
            if(itemSub)
            {
                if(_interactive)
                {
                    if(Box::yesNo(strFmt("Ordered item number %1 will be replaced by substitute item number %2",
                        parentChild.ChildItemID,
                        parentChild.ParentItemID), DialogButton::No) == DialogButton::Yes)
                    {
                        replacementItemID = itemSub.SubstituteItemId;
                    }
                    else
                    {
                        // Prompted for replacement based on 'Always' substitution but user did not confirm.
                        ret = false;
                    }
                }
                else
                {
                    replacementItemID = itemSub.SubstituteItemId;
                }
            }

        }

        if(replacementItemID)
        {
                            
        }
        return ret;
    }

    /// <summary>
    /// Check substitution updates at point of reservation. Relates to the non-"Always"
    /// substitution codes (Never, out of stock, etc).
    /// TBD requirements around delayed/date-based reservation.
    /// The batch process or service used to trigger date-based reservation will 
    /// need to call this function, possibly accepting back a new/replacement SalesLine.
    /// </summary>
    /// <param name = "_salesLine"></param>
    /// <param name = "_interactive"></param>
    /// <returns></returns>
    public static boolean checkSalesLineAtReservation(
        SalesLine               _salesLine,
        boolean                 _interactive = true)
    {
        boolean                                 ret = true;

        METSalesItemSubstitute                  itemSub;
        METSalesItemSubstitutionParentChild     parentChild;
        ItemId                                  replacementItemID;
        InventDim                               inventDim   = _salesLine.inventDim();
        SalesTable                              salesTable  = _salesLine.salesTable();
        METSalesItemSubstitutionAccountRelation subsGroup   = salesTable.custTable_CustAccount().CustGroup;
        date                                    todayDate   = DateTimeUtil::getToday(DateTimeUtil::getClientMachineTimeZone());

        InventOnhand                            onHand;
        InventDimParm                           dimParm;

        if(!_salesLine.metSubstitutionsActive())
        {
            return true;
        }

        dimParm.initFromInventDim(inventDim);
        onHand = InventOnhand::newItemDim(_salesLine.ItemId, inventDim, dimParm);
        Qty currentOnHand = onHand.availOrdered();  // ** Confirm if ordered qty should be included.

        if(currentOnHand >= _salesLine.QtyOrdered)
        {
            // Sufficient stock on-hand. No replacement needed.
            return true;
        }
        else
        {

            select firstonly validTimeState(todayDate) * from itemSub
                order by AccountCode asc
                where   itemSub.ItemId              == _salesLine.ItemId
                &&      itemSub.InventSiteId        == inventDim.InventSiteId
                &&      itemSub.SubstitutionCode    == METSalesItemSubstitutionCode::Never
                &&  (   // table/group/all match
                    (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::Table &&
                     itemSub.AccountRelation == salesTable.CustAccount)
                ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::GroupId &&
                     itemSub.AccountRelation == subsGroup)
                ||  (itemSub.AccountCode == METSalesItemSubstitutionAccountCodeType::All &&
                     itemSub.AccountRelation == '')
                );

            if(itemSub)
            {
                // "Never" substitution entry found.                   
            }

        }

        return ret;

    }
